function findEntriesInDotNotation(obj, dotString) {
    const parts = dotString.split('.');
    let currentObj = obj;

    for (let part of parts) {
        if (!currentObj || typeof currentObj !== 'object') {
            throw new Error(`Invalid dot notation: ${dotString}`);
        }

        // Check if the current key exists in the object.
        if (!(part in currentObj)) {
            throw new Error(`Key not found: ${part} in ${dotString}`);
        }

        // Recursively search for more nested keys.
        currentObj = currentObj[part];
    }

    return currentObj;
}

